package com.mohymods.kingdomsmp.integration.ftbquests;

import com.mohymods.kingdomsmp.kingdom.AlphaScope;
import com.mohymods.kingdomsmp.profession.*;
import net.minecraft.nbt.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.*;

/** Additive, rewardless alpha guide. Existing settlement chapters and saved team records keep their IDs. */
public final class AlphaQuestCampaign {
    public static final String TAG_PREFIX="kingdom_smp:alpha_guide/", PREFIX=TAG_PREFIX+"v1/";
    public static final long KINGDOM_CHAPTER=0x4B534D5000130000L, FUTURE_CHAPTER=KINGDOM_CHAPTER+7;
    public static final List<Profession> ROLES=List.of(Profession.FARMER,Profession.BLACKSMITH,Profession.BUILDER,Profession.LUMBERJACK,Profession.MINER,Profession.LIBRARIAN);
    public enum Kind { TIER, BUILDING, PROFESSION, FUTURE }
    public record Goal(String key,long chapterId,long questId,long taskId,Kind kind,String fact,int tier,String title,String icon,List<String> description,List<Long> prerequisites,int column,int row) {
        public Goal { description=List.copyOf(description);prerequisites=List.copyOf(prerequisites); }
        public String tag(){return PREFIX+key;}
        public boolean complete(KingdomQuestSnapshot shared,Set<String> earned){
            if(kind==Kind.FUTURE||shared.tier()<tier)return false;
            return switch(kind){case TIER->true;case BUILDING->shared.completedBuildingIds().contains(fact);case PROFESSION->earned.contains(fact);case FUTURE->false;};
        }
    }
    private static final List<Goal> GOALS=create();
    private static final Map<String,Goal> TAGS;
    static {Map<String,Goal> map=new HashMap<>();for(var g:GOALS)if(map.put(g.tag(),g)!=null)throw new IllegalStateException("Duplicate alpha guide tag");TAGS=Map.copyOf(map);}
    private AlphaQuestCampaign() { }
    public static List<Goal> goals(){return GOALS;}
    public static Optional<Goal> parse(String tag){return tag==null?Optional.empty():Optional.ofNullable(TAGS.get(tag));}
    private static String code(long id){return String.format(Locale.ROOT,"%016X",id);}
    private static long id(int section,int index){return KINGDOM_CHAPTER+0x10000L+section*0x1000L+index;}
    private static long tierQuest(int tier){return tier==2?KingdomQuestGoal.TIER_TWO.questId():tier==3?KingdomQuestGoal.TIER_THREE.questId():id(0,tier-3);}
    private static Goal goal(int section,int index,String key,Kind kind,String fact,int tier,String title,String icon,List<String> text,List<Long> prior,int x,int y){return new Goal(key,KINGDOM_CHAPTER+section,id(section,index),id(section,index)+0x100000L,kind,fact,tier,title,icon,text,prior,x,y);}
    private static List<Goal> create(){
        List<Goal> rows=new ArrayList<>();
        String[] titles={"Tier 4 — The Aether opens","Tier 5 — Into the Nether","Tier 6 — Twilight and aviation"};
        String[] icons={"minecraft:diamond","minecraft:quartz","minecraft:ender_pearl"};
        String[] details={"At the maintained Hall, contribute the live Tier 3 targets. The intact staffed Bank and Hut remain required. These costs use accessible Overworld resources; no Nether or End material is needed.","Complete the live Tier 4 counter at the Hall. Nether access opens only after this earned transition. The targets are still obtainable without Nether materials.","Complete the live Tier 5 counter using already unlocked Nether and Overworld supplies. Twilight Forest opens at Tier 6. Tier 6 alone does not authorize aircraft: complete the Aerodrome too."};
        for(int tier=4;tier<=6;tier++)rows.add(goal(0,tier-3,"tier_"+tier,Kind.TIER,"",tier,titles[tier-4],icons[tier-4],List.of(details[tier-4],"Use K → Progression for exact pinned quantities and remaining donations. Partial contributions and standings are persistent. This guide never changes a tier or grants materials."),List.of(tier==4?KingdomQuestGoal.BANK.questId():tierQuest(tier-1)),tier-4,0));
        rows.add(goal(0,4,"aerodrome",Kind.BUILDING,"kingdom_smp:royal_aerodrome",6,"A kingdom takes flight","minecraft:phantom_membrane",List.of("At earned Tier 6, purchase the sole Aerodrome plan through the Royal Architect, choose and approve the supported hologram site, then let original Aldric complete the hangar.","Visit Corin for the implemented aircraft services. Native aircraft access requires Tier 6 AND the completed intact Aerodrome; damage and claim restrictions still apply. Buyer registration can share access.","This is a committed construction achievement, not a bypass of current service, repair, fuel or ownership checks."),List.of(tierQuest(6)),3,0));
        for(int section=1;section<=ROLES.size();section++){
            var role=ROLES.get(section-1);String icon=icon(role);int premiseTier=premiseTier(role);
            rows.add(goal(section,1,role.id()+"/premise",Kind.BUILDING,role.buildingId(),premiseTier,"A home for the "+display(role),icon,List.of("Purchase the profession building at its real unlock tier, position its authenticated plan and have Aldric complete it. Meet its named resident to enroll.","Up to three professions may be active. Switching costs 15,000 coins; inactive progress is preserved. Buy earned equipment at its own maintained staffed building.","FTB displays team achievements: a teammate's earned quest can mark this guide. YOUR rank and all rewards always come from your personal Kingdom record in K → Professions. No FTB completion, reset or team change grants XP, equipment or coins."),List.of(KingdomQuestGoal.HEADQUARTERS.questId()),0,-2));
            for(var band:ProfessionRank.values())for(int n=1;n<=8;n++){
                String quest=role.questId(band,n);var slot=ProfessionQuestService.catalog().definition(quest).orElseThrow();List<Long> prior=new ArrayList<>();prior.add(id(section,1));
                slot.prerequisites().stream().sorted().forEach(p->prior.add(professionQuestId(role,p)));
                if(band!=ProfessionRank.APPRENTICE)for(int a=1;a<=8;a++)prior.add(professionQuestId(role,role.questId(ProfessionRank.values()[band.ordinal()-1],a)));
                int tier=role==Profession.FARMER?premiseTier:AlphaScope.questTier(quest);// Live tier is checked by the predicate; old earned professions must not depend on rebuilding a later guide chain.
                String objective=role==Profession.FARMER?farmerObjective(band,n):ApprovedProfessionContent.get(quest).objective();
                if(role==Profession.LIBRARIAN&&band==ProfessionRank.MASTER)objective=libraryMaster(n);
                String title=role==Profession.FARMER?FarmerQuests.title(quest):ProfessionQuestService.title(quest);
                rows.add(goal(section,2+band.ordinal()*8+n-1,quest.substring("kingdom_smp:".length()),Kind.PROFESSION,quest,tier,(band.ordinal()+1)+"."+n+" — "+title,icon,List.of(objective,"Open K → Professions at the resident for current configurable quantities and validated gameplay evidence. Inspected objectives need a real on-site operator review/confirmation; ordinary completion packets cannot grant them.","Recognition: "+((band.ordinal()+1)*100)+" XP, awarded once by Kingdom SMP. Completing all 8 Apprentice quests opens Journeyman; all 24 earn Master purchase rights. Equipment is purchased separately, never granted here.","Team guide only. Only your own completed canonical Kingdom quests advance YOUR rank; FTB stores no profession authority."),prior.stream().distinct().toList(),n-1,band.ordinal()*2));
            }
        }
        for(var role:Profession.values())if(!AlphaScope.selected(role))rows.add(goal(7,1+role.ordinal(),"future/"+role.id(),Kind.FUTURE,"",1,display(role)+" — Coming Soon","minecraft:barrier",List.of("AVAILABLE IN A FUTURE UPDATE. Existing working lower-rank content and every saved profession record are preserved in K → Professions.","Unfinished ranks, quests, abilities and equipment do not accept completion or purchases. This informational guide entry cannot award progress."),List.of(),role.ordinal()%6,0));
        for(int tier=7;tier<=12;tier++)rows.add(goal(7,32+tier,"future/tier_"+tier,Kind.FUTURE,"",tier,"Tier "+tier+" — Future Update","minecraft:barrier",List.of(AlphaScope.futureMessage(),"This alpha cannot earn Tier 7–12 or unlock their dimensions, buildings, technology or rewards. Historical attained tiers and records are preserved. The End remains a Tier 12 future finale."),List.of(),tier-7,2));
        return List.copyOf(rows);
    }
    private static long professionQuestId(Profession role,String quest){var d=ProfessionQuestService.catalog().definition(quest).orElseThrow();return id(ROLES.indexOf(role)+1,2+d.rank().ordinal()*8+d.ordinal()-1);}
    private static int premiseTier(Profession role){return switch(role){case FARMER,BUILDER,LUMBERJACK->2;default->com.mohymods.kingdomsmp.building.ProfessionPremises.get(net.minecraft.resources.ResourceLocation.parse(role.buildingId())).tier();};}
    private static String icon(Profession role){return switch(role){case FARMER->"minecraft:wheat";case BLACKSMITH->"minecraft:anvil";case BUILDER->"minecraft:bricks";case LUMBERJACK->"minecraft:iron_axe";case MINER->"minecraft:iron_pickaxe";case LIBRARIAN->"minecraft:enchanted_book";default->"minecraft:book";};}
    private static String display(Profession role){String s=role.id();return Character.toUpperCase(s.charAt(0))+s.substring(1);}
    private static String farmerObjective(ProfessionRank band,int n){String[] rows={
        "Use a hoe to prepare32real farmland blocks through permitted native interaction.","Harvest128mature wheat from personally planted tracked crops.","Harvest64mature carrots from personally planted tracked crops.","Harvest64mature potatoes from personally planted tracked crops.","Breed8unique farm offspring through real husbandry.","Craft32bread through native crafting; permanent community bread delivery proves the consumed production.","Permanently deliver32bread to the Farmer; real native production and inventory debit are required.","Request an on-site inspection of your working farm, crops, water, paths and appropriate storage.",
        "Harvest256beetroot and256wheat in the Journeyman band from tracked mature crops.","Harvest256carrots and256potatoes in the Journeyman band.","Harvest128genuine stem-grown melons/pumpkins; placed produce cannot count.","Breed8unique cows,8sheep and8chickens during this band.","Deliver64eggs and32milk buckets; contents are consumed and legitimate empty containers returned.","Produce and permanently deliver16celebration cakes.","Complete five distinct funded daily Farmer service periods in this band.","Request inspection of shared irrigation and a functioning, accessible farm.",
        "Harvest1,024tracked mature crops in the Master band, with at least128each wheat, carrot, potato and beetroot.","Breed16unique offspring across cows, sheep, chickens and pigs, including at least two of each.","Deliver64bread,4cakes,32pumpkin pies and16beetroot soups for the kingdom banquet. Actual contents are consumed with correct container accounting.","Complete two distinct funded weekly Farmer service periods in this band.","Help complete three real Bounty Hall community food projects with at least10percent personal supply per project. Maintain the completed Tier3Bounty Hall.","Complete128personally planted seed-to-mature harvests followed by actual seed-funded replanting.","Request on-site inspection of a functioning agricultural estate with current protected access and appropriate facilities.","After the other seven Master proofs, request the final Farmer stewardship inspection. Master grants purchase rights, not free equipment."};return rows[band.ordinal()*8+n-1]+" These are configurable default quantities; the live Farmer counter is authoritative.";}
    private static String libraryMaster(int n){return switch(n){case 1->"ALPHA TIER 6: six newly authenticated maximum-native-level books spanning at least three enchantment families. Real native paid work and permanent delivery; the live counter uses the configured quantity.";case 2->"ALPHA TIER 6: six different enabled native Ars Tier 2 glyphs, consumed during an on-site inspected archive delivery. The original Tier 3 archive is Future Update.";case 3->"ALPHA TIER 6: six different enabled craftable native RARE spell IDs, consumed during inspected archive delivery. Original EPIC archive is Future Update.";case 4->"ALPHA TIER 6: personally explore Twilight Forest in the Master band and submit a genuinely observed, signed readable field volume. Old Journeyman observations do not substitute. Original Otherside objective is Future Update.";case 5->"Four new successful compatible native maintenance jobs for at least two explicitly consenting current inventory owners. Pay real materials/XP and return each physical output through private mail. Old Journeyman jobs never count again.";case 6->"Complete five distinct funded daily Master service periods at the Library. Exact native delivery and finite payment are persistent; configurable periods are shown live.";case 7->"Write and display a signed readable six-subject kingdom reference collection: kingdom, dimensions, construction, economy, professions and magic. Request an on-site inspection of its accuracy and accessibility.";case 8->"After all seven Master proofs, request the final live Library assessment. Maintain the actual collection, Master expedition volume, catalogues, enchanting/bookbinding facilities, safe access and current claim permissions.";default->throw new IllegalArgumentException();};}
    public static Map<String,KingdomQuestCampaign.Result> install(Path directory)throws IOException{
        Map<String,KingdomQuestCampaign.Result> result=new LinkedHashMap<>();for(int section=0;section<=7;section++){String filename="kingdom_smp_alpha_v1_"+section+".snbt";byte[] bytes=chapter(section).toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>128*1024)throw new IOException("Alpha chapter too large");result.put(filename,KingdomQuestCampaign.publish(directory,filename,bytes));}return Map.copyOf(result);
    }
    static CompoundTag chapter(int section){
        var chapter=new CompoundTag();chapter.putString("id",code(KINGDOM_CHAPTER+section));chapter.putString("filename","kingdom_smp_alpha_v1_"+section);chapter.putString("title",section==0?"Kingdom SMP — Tier 4–6":section==7?"Kingdom SMP — Coming Soon":"Kingdom SMP — "+display(ROLES.get(section-1)));chapter.put("icon",iconTag(section==0?"minecraft:campfire":section==7?"minecraft:barrier":icon(ROLES.get(section-1))));chapter.putString("group","");chapter.putInt("order_index",section);chapter.putString("default_quest_shape","square");var quests=new ListTag();
        for(var g:GOALS)if(g.chapterId()==KINGDOM_CHAPTER+section){var q=new CompoundTag();q.putString("id",code(g.questId()));q.putString("title",g.title());q.put("icon",iconTag(g.icon()));q.putDouble("x",g.column()*2.0);q.putDouble("y",g.row()*2.0);var deps=new ListTag();g.prerequisites().forEach(p->deps.add(StringTag.valueOf(code(p))));q.put("dependencies",deps);var text=new ListTag();g.description().forEach(p->text.add(StringTag.valueOf(p)));q.put("description",text);var task=new CompoundTag();task.putString("id",code(g.taskId()));task.putString("type","custom");task.put("icon",iconTag(g.icon()));var tags=new ListTag();tags.add(StringTag.valueOf(g.tag()));task.put("tags",tags);var tasks=new ListTag();tasks.add(task);q.put("tasks",tasks);q.put("rewards",new ListTag());quests.add(q);}chapter.put("quests",quests);return chapter;
    }
    private static CompoundTag iconTag(String id){var icon=new CompoundTag();icon.putString("id",id);return icon;}
}
